// 判断一名选手的成绩是否异常
bool isAbnormal(const vector<long long>& a, int r,
                const vector<int>& passed) {
    int maxIndex = 0;

    // 检查规则二，同时求通过的最大题目编号
    for (int i = 0; i < static_cast<int>(passed.size()); i++) {
        maxIndex = max(maxIndex, passed[i]);

        if (i > 0 && abs(passed[i] - passed[i - 1]) >= r) {
            return true;
